import{_ as a,o,c as n,a2 as t}from"./chunks/framework.CqGPl1zp.js";const r="/newx-doc/assets/%E5%A6%82%E4%BD%95%E4%BD%BF%E7%94%A8.DEOZdosi.png",_=JSON.parse('{"title":"1. 推理模式（thinking）","description":"","frontmatter":{},"headers":[],"relativePath":"ai/thinking.md","filePath":"ai/thinking.md","lastUpdated":null}'),i={name:"ai/thinking.md"};function c(d,e,p,s,l,h){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="_1-推理模式-thinking" tabindex="-1">1. 推理模式（thinking） <a class="header-anchor" href="#_1-推理模式-thinking" aria-label="Permalink to &quot;1. 推理模式（thinking）&quot;">​</a></h1><p>对于支持「推理模式」的模型来说，在输出最终回答之前，模型会先输出一段思维链内容，以提升最终答案的准确性。</p><p>说人话，就是在每一轮对话过程中，模型会输出思维链内容（<code>reasoning_content</code>）和最终回答（<code>content</code>）。对应到 <code>ai_chat_message</code> 表里，就是 <code>reasoning_content</code> 字段和 <code>content</code> 字段。</p><h1 id="_2-如何使用" tabindex="-1">2. 如何使用？ <a class="header-anchor" href="#_2-如何使用" aria-label="Permalink to &quot;2. 如何使用？&quot;">​</a></h1><p>AI 对话时，使用支持「推理模式」的模型（如 <code>deepseek-reasoner</code>、<code>qwen3</code> 等）时，模型返回结果就会包含思维链内容。如下图所示：</p><p><img src="'+r+'" alt="如何使用"></p><h1 id="_3-哪些模型平台支持" tabindex="-1">3. 哪些模型平台支持？ <a class="header-anchor" href="#_3-哪些模型平台支持" aria-label="Permalink to &quot;3. 哪些模型平台支持？&quot;">​</a></h1><p>基本上，目前所有模型平台，都有支持「推理模式」的模型。目前碰到的问题，更多的还是 Spring AI 是否对该模型（平台）提供了支持。</p><h3 id="_3-1-spring-ai-已支持" tabindex="-1">3.1 Spring AI 已支持 <a class="header-anchor" href="#_3-1-spring-ai-已支持" aria-label="Permalink to &quot;3.1 Spring AI 已支持&quot;">​</a></h3><p>友情提示：如下是我测试过的一些模型！</p><p>一般情况下，你可以使用对应模型的 ChatModelTests 类的 <code>#testStream_thinking()</code> 方法，搞了大几个小时！</p><p>① DeepSeek：<a href="https://api-docs.deepseek.com/zh-cn/guides/reasoning_model" target="_blank" rel="noreferrer"><code>deepseek-reasoner</code></a></p><p>② 通义千问：<code>qwen3</code>、<code>qwen-max</code> 等，可见 <a href="https://bailian.console.aliyun.com/?spm=a2c4g.11186623.0.0.910360e9E3uq3z&amp;tab=model#/model-market?capabilities=%5B%22QwQ%22%5D&amp;z_type_=%7B%22capabilities%22%3A%22array%22%7D" target="_blank" rel="noreferrer">《阿里云 —— 模型广场》</a> 的「推理模型」类型。</p><p>③ 字节豆包：<code>Doubao-Seed-1.6-thinking</code> 等，可见 <a href="https://console.volcengine.com/ark/region:ark+cn-beijing/model?vendor=Bytedance&amp;view=DEFAULT_VIEW" target="_blank" rel="noreferrer">《火山引擎 —— 模型广场》</a> 的「深度思考」类别。</p><p>④ 腾讯混元：<code>hunyuan-a13b</code> 等，可见 <a href="https://cloud.tencent.com/document/product/1729/104753" target="_blank" rel="noreferrer">《混元大模型 —— 产品概述》</a> 文档。</p><p>⑤ 硅基流动：<code>deepseek-ai/DeepSeek-R1</code> 等，可见 <a href="https://cloud.siliconflow.cn/me/models?tags=%E6%8E%A8%E7%90%86%E6%A8%A1%E5%9E%8B" target="_blank" rel="noreferrer">《硅基流动 —— 模型广场》</a> 的「推理模型」标签。</p><p>⑥ 讯飞星火：<code>x1</code> 等，可见 <a href="https://www.xfyun.cn/doc/spark/X1http.html" target="_blank" rel="noreferrer">《星火大模型 X1》</a> 文档。</p><h3 id="_3-2-spring-ai-未支持" tabindex="-1">3.2 Spring AI 未支持 <a class="header-anchor" href="#_3-2-spring-ai-未支持" aria-label="Permalink to &quot;3.2 Spring AI 未支持&quot;">​</a></h3><p>① OpenAI：需要基于它的 Responses API，可见 <a href="https://github.com/spring-projects/spring-ai/issues/2962" target="_blank" rel="noreferrer">https://github.com/spring-projects/spring-ai/issues/2962</a> 讨论。</p><h3 id="_3-3-其它" tabindex="-1">3.3 其它 <a class="header-anchor" href="#_3-3-其它" aria-label="Permalink to &quot;3.3 其它&quot;">​</a></h3><p>① BaiChuan：暂未跟进</p><p>② Coze、Dify：是 AI 工作流，暂时也不会返回执行过程中的思维链。</p><h2 id="_4-thinking-模式的开关" tabindex="-1">4. thinking 模式的开关 <a class="header-anchor" href="#_4-thinking-模式的开关" aria-label="Permalink to &quot;4. thinking 模式的开关&quot;">​</a></h2><p>【模型标识】类似 DeepSeek-V3.1，是通过 <code>deepseek-chat</code> 对应 DeepSeek-V3.1 的非思考模式，<code>deepseek-reasoner</code> 对应 DeepSeek-V3.1 的思考模式。</p><p>但是我们会发现，很多模型会开始使用相同的【模型标识】，通过类似 <code>thinking</code> 参数，来控制是否开启「推理模式」。例如说：</p><ul><li>OpenAI：<code>reasoning_effort</code> 有 <code>low</code>、<code>medium</code>、<code>high</code> 三个等级</li><li>Claude：<code>thinking</code> + <code>budget_tokens</code> 思考深度</li><li>通义千问：<code>enable_thinking</code> 开关</li><li>字节豆包：<code>thinking</code> 开关，<a href="https://www.volcengine.com/docs/82379/1494384" target="_blank" rel="noreferrer">https://www.volcengine.com/docs/82379/1494384</a></li></ul><p>后续，我们应该要在「模型配置」功能里，增加对应的 <code>thinking</code> 配置。这样，后续用户在对话界面，使用推理模型时，可手动开启或关闭「推理模式」。类似现在豆包、元宝等平台的做法。</p><p>TODO</p>',28)])])}const k=a(i,[["render",c]]);export{_ as __pageData,k as default};
